    /// <summary>
    /// The interval period and timezone to apply to returned metrics. o IntervalPeriod : An aggregated grouping applied to request met- rics. Valid IntervalPeriod values are: FIFTEEN_MIN | THIRTY_MIN | HOUR | DAY | WEEK | TOTAL . For example, if IntervalPeriod is se- lected THIRTY_MIN , StartTime and EndTime differs by 1 day, then Connect Customer returns 48 results in the response. Each result is aggregated by the THIRTY_MIN period. By default Connect Cus- tomer aggregates results based on the TOTAL interval period. The following list describes restrictions on StartTime and EndTime based on which IntervalPeriod is requested. o FIFTEEN_MIN : The difference between StartTime and EndTime must be less than 3 days. o THIRTY_MIN : The difference between StartTime and EndTime must be less than 3 days. o HOUR : The difference between StartTime and EndTime must be less than 3 days. o DAY : The difference between StartTime and EndTime must be less than 35 days. o WEEK : The difference between StartTime and EndTime must be less than 35 days. o TOTAL : The difference between StartTime and EndTime must be less than 35 days. o TimeZone : The timezone applied to requested metrics. TimeZone -&gt; (string) The timezone applied to requested metrics. IntervalPeriod -&gt; (string) IntervalPeriod : An aggregated grouping applied to request metrics. Valid IntervalPeriod values are: FIFTEEN_MIN | THIRTY_MIN | HOUR | DAY | WEEK | TOTAL . For example, if IntervalPeriod is selected THIRTY_MIN , Start- Time and EndTime differs by 1 day, then Connect Customer returns 48 results in the response. Each result is aggregated by the THIRTY_MIN period. By default Connect Customer aggregates re- sults based on the TOTAL interval period. The following list describes restrictions on StartTime and End- Time based on what IntervalPeriod is requested. o FIFTEEN_MIN : The difference between StartTime and EndTime must be less than 3 days. o THIRTY_MIN : The difference between StartTime and EndTime must be less than 3 days. o HOUR : The difference between StartTime and EndTime must be less than 3 days. o DAY : The difference between StartTime and EndTime must be less than 35 days. o WEEK : The difference between StartTime and EndTime must be less than 35 days. o TOTAL : The difference between StartTime and EndTime must be less than 35 days. Possible values: o FIFTEEN_MIN o THIRTY_MIN o HOUR o DAY o WEEK o TOTAL Shorthand Syntax: TimeZone=string,IntervalPeriod=string JSON Syntax: { "TimeZone": "string", "IntervalPeriod": "FIFTEEN_MIN"|"THIRTY_MIN"|"HOUR"|"DAY"|"WEEK"|"TOTAL" }
    /// </summary>
    [CliOption("--interval")]
    public string? Interval { get; set; }

